const body = $json.body || $json;
const { service_slug, user_id, answers } = body;

if (!user_id) {
  return [{ json: { _valid: false, _error: 'missing user_id' } }];
}
if (!service_slug) {
  return [{ json: { _valid: false, _error: 'missing service_slug' } }];
}
if (!answers || Object.keys(answers).length === 0) {
  return [{ json: { _valid: false, _error: 'empty answers' } }];
}

return [{
  json: {
    _valid: true,
    _user_id: String(user_id),
    _service_slug: service_slug,
    _answers: answers,
    _submitted_at: new Date().toISOString()
  }
}];

