const content = $('Generate Document').item.json?.choices?.[0]?.message?.content || 'Помилка генерації документа.';
const caseId = $('Insert Case').item.json.id;
return [{ json: { _content: content, _case_id: caseId } }];

const content = $('Prepare Content').item.json._content;
const newDocId = $json.id;
return [{
  json: {
    _new_doc_id: newDocId,
    _new_doc_url: 'https://docs.google.com/document/d/' + newDocId + '/edit',
    _batch_request: {
      requests: [{
        replaceAllText: {
          containsText: { text: '{{DOCUMENT_CONTENT}}', matchCase: true },
          replaceText: content
        }
      }]
    }
  }
}];
